/**
 * Shared srcset/sizes for the case-study screens generated by
 * scripts/build-work-images.mjs (`npm run images`).
 *
 * Every screen exists as `<name>.webp` (2400px, for high-density screens) and
 * `<name>-1200.webp` (1200px). The asset components render a raw <img> with
 * these rather than next/image: the WebPs are already encoded for UI screenshots
 * (sharp-YUV), and the optimizer would re-encode them a second time without it.
 */

/** Width of the small candidate the build script writes. */
const SMALL_WIDTH = 1200;

/** `srcset` for a generated screen at `base` (no extension), `w` px wide. */
export function workSrcSet(base: string, w: number): string {
  // A master narrower than the small size (a phone frame) comes out the same
  // width twice, and two candidates with one descriptor is an invalid srcset.
  if (w <= SMALL_WIDTH) return `${base}-1200.webp ${w}w`;
  return `${base}-1200.webp ${SMALL_WIDTH}w, ${base}.webp ${w}w`;
}

/**
 * A phone capture, shown at phone width (`max-w-sm`, 384px) rather than
 * stretched across the column, where a 1:4 frame would run ~4,000px tall.
 */
export const PHONE_SIZES = "(min-width: 432px) 384px, calc(100vw - 3rem)";

/**
 * Rendered width of a case-study scene: the Container is max-w-6xl (1152px)
 * with px-8 from sm (px-6 below), so the column tops out at 1088px. Telling the
 * browser this lets a DPR-1 screen take the 1200px file and a DPR-2 screen the
 * 2400px one, instead of guessing from the viewport.
 */
export const CASE_STUDY_SIZES =
  "(min-width: 1152px) 1088px, (min-width: 640px) calc(100vw - 4rem), calc(100vw - 3rem)";

/** A Work-grid card: 526px in the 2-up grid from md, full-bleed below. */
export const CARD_SIZES = "(min-width: 768px) 526px, 100vw";
